#!/usr/bin/env python3
"""Render a self-contained proposal using the unchanged house-style CSS."""
import html,json,pathlib
from study import ROOT,POP
css=(ROOT/'house-style.css').read_text()
head='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Russian for phone thumbs — research proposal</title><style>'+css+'</style></head><body><main>\n'
r=json.loads((ROOT/'results.json').read_text()); c=json.loads((ROOT/'counts.json').read_text())
source='https://github.com/shofel/pixel-tools/blob/9d64db0a5d27e4c5eb20e73820f2ea6dbc3b0d0a/boo-keyboard/'
def link(f,label,anchor=''):return f'<a href="{source+f+anchor}">{label}</a>'
def board(layout):
    rows=[list(layout[i:i+10]) for i in range(0,30,10)]
    rows.append(['','','NUM','SYM','⇧','↵','␣','⌫','',''])
    cells=[]
    for ri,row in enumerate(rows):
        for ci,ch in enumerate(row):
            x=ci*9.4+(6 if ci>=5 else 0)
            tip=next((p for p,b in POP.items() if b==ch),'')
            label=html.escape(ch)
            if tip:label+=f'<tspan x="{x+4.7}" dy="3.3" font-size="2.5">hold: {tip}</tspan>'
            cells.append(f'<rect x="{x+.2}" y="{ri*15+.2}" width="9" height="14.6" rx="1" fill="currentColor" opacity="{.09 if ch else .025}"/><text x="{x+4.7}" y="{ri*15+7}" text-anchor="middle" font-size="{3 if len(ch)>1 else 4.5}" fill="currentColor">{label}</text>')
    return '<svg role="img" aria-label="Proposed Russian phone touch grid; left thumb left half, right thumb right half" viewBox="0 0 100 60" style="width:100%;max-width:650px">'+''.join(cells)+'</svg>'
a=r['sensitivity']['vertical_pitch_1_popup_3']; e=r['extra_test_checks']['vertical_1_anchor_L2_R7']
metrics=[('Whole path of each thumb, including intervening other-thumb taps (u/character)',e['baseline']['each_thumb_path_u_per_character'],e['candidate']['each_thumb_path_u_per_character']),('Consecutive same-thumb travel (u/pair)',a['baseline']['same_thumb_travel_u_per_pair'],a['candidate']['same_thumb_travel_u_per_pair']),('Reach from assumed lower-center anchor (u/character)',a['baseline']['mean_anchor_reach_u'],a['candidate']['mean_anchor_reach_u']),('Long moves over 3u (per 100 characters)',e['baseline']['long_thumb_moves_over_3u_per_100_chars'],e['candidate']['long_thumb_moves_over_3u_per_100_chars']),('Space-adjacent same-thumb travel (u/Space-adjacent pair)',e['baseline']['space_adjacent_same_thumb_travel_u_per_space_pair'],e['candidate']['space_adjacent_same_thumb_travel_u_per_space_pair'])]
table='<table style="width:100%;text-align:left"><thead><tr><th>Held-out model measure ↓</th><th>v24</th><th>Candidate</th><th>Change</th></tr></thead><tbody>'+''.join(f'<tr><td>{n}</td><td>{b:.3f}</td><td>{v:.3f}</td><td>{(v/b-1)*100:.1f}%</td></tr>' for n,b,v in metrics)+'</tbody></table>'
body=f'''<header><p class="muted">2Thumbs · Russian · phone touchscreen only · research, not implementation</p><h1>I recovered the phone grid and found a lower-travel Russian candidate; keep it a proposal until thumb reach is checked.</h1></header>
<section class="card pass"><strong>I verified the source geometry and measured one public corpus.</strong><p>The candidate preserves the shipped touch cells, footer and all 33 Russian letters. On unseen public test text, modeled complete thumb travel falls 12.5%. No phone interaction or application changes were made.</p></section>
<section class="card pending"><strong>I have not measured your phone or your thumbs.</strong><p>Actual target sizes, grip, comfortable reach arcs and typing experience are unknown. One plausible inner-thumb posture reverses the modeled reach advantage. This is not a speed, accuracy or comfort claim, and no new user request is needed now.</p></section>
<ol class="steps">
<li><h2>Start from the recovered shipped phone geometry</h2><p>Each half has five columns and three alphabet rows, plus one footer. Every cell is <strong>9.4% of keyboard width</strong>; the full-height gap spans <strong>47–53%</strong>. All cells are phone touch zones, not physical keys or finger columns.</p><pre>v24 Russian:
й ц у к е   н г ш щ з
ф ы в а п   р о л д ж
я ч с м и   т ь б ю х
· · NUM SYM ⇧   ↵ ␣ ⌫ · ·</pre>
<p>Left thumb owns every left-half touch target; right thumb owns every right-half target, including Space, Return and Backspace. No other fingers are assigned. Russian popups are е→ё, ь→ъ, ж→э.</p><p>Column centers, as percentages of width: left 4.7, 14.1, 23.5, 32.9, 42.3; right 57.7, 67.1, 76.5, 85.9, 95.3. These are ideal source cell centers, not measured Android hit bounds or millimeters. Vertical pitch is modeled, not recovered as a universal physical size.</p>
<p>Sources: {link('SPEC.html','current spec','#L1')}, {link('d_layout.py','unit/gap generator')}, {link('russian_layout.py','Russian generator')}, {link('next_layout.py','footer and NUM generator')}.</p><p class="see"><strong>You should see:</strong> the accepted v24 arrangement, not Cantor geometry or the unfinished next draft.</p></li>
<li><h2>Consider this candidate within the same touch zones</h2><p><strong>Left thumb on the left; right thumb on the right. All targets remain 1u.</strong> The illustration is a schematic, not a phone screenshot; its row proportions are not measurements.</p>{board(r['candidate'])}<pre>б л д з х   ю щ ж ц ш
г к с в й   ь у е ч ф
п р т н м   я и о а ы
· · NUM SYM ⇧   ↵ ␣ ⌫ · ·</pre><p>Popups travel with their base letters: hold е→ё (right middle row), ь→ъ (right middle row), ж→э (right top row). Thirty letters stay direct; no new gesture is proposed. Common о/а/и are near the assumed right lower-center anchor; н/т/р are near the left one. This explains the result, not a claim about your natural reach.</p><p class="see"><strong>You should see:</strong> an alphabet-only proposal; no hidden footer, target-size or layer redesign.</p></li>
<li><h2>Compare both layouts on exactly the same unseen text</h2>{table}<p>One u is one horizontal cell pitch (9.4% of keyboard width). The complete-path measure tracks each thumb from its previous own tap even while the other thumb types; it does not assume alternating taps erase movement. Initial positions reset per sentence and are not charged.</p><p>Same-thumb adjacent pairs: <strong>42.61% → 29.92%</strong>, including same-target repeats (1.25% both). Right-thumb load including Space: <strong>52.62% → 54.03%</strong>; the candidate is slightly less balanced. Same-thumb percentage is diagnostic, not an eight-finger SFB metric or a stand-alone optimum.</p><p>Space is 13.08% of test characters and stays right-footer second cell; all 16,308 Space-adjacent pairs are included. Both layouts represent 100% of the Russian-letter-plus-space test mass and all 33 Russian letters, with <strong>0.492% popup letters</strong>. Identical popup incidence means hold penalties cannot manufacture a candidate advantage.</p><p class="see"><strong>You should see:</strong> new public-corpus model measurements, not the historical private-corpus figures.</p></li>
<li><h2>Keep controls and unfinished product ideas separate</h2><p>Current left NUM/SYM: tap-toggle under 200 ms, hold/chord momentary. Right Return/Space: ordinary taps; holds open SYM/NUM at native timeout, with Space-swipe arbitration. Their exact locations stay fixed. For right-hand NUM digits, use left NUM; for left-hand symbols, right Return hold frees the left thumb. Opposite-hand holds do not grant a thumb a second simultaneous contact; a symbol on the holding thumb's side may need a latched layer instead.</p><p>Shift remains the current alphabet control. The draft discusses moving it, but the location/semantics are unresolved. No digits on letters, double-space period, Dvorak apostrophe, NUM punctuation changes and BOO/QWERTY replacement are <strong>draft directions, not implemented baseline behavior</strong>. This proposal neither implements nor decides them. If digit popups are retained, their column-order choices should be kept separately from the three Russian popup defaults.</p><p>Punctuation and layer actions are not scored as if they vanished: they are explicitly <strong>outside this letter-and-space corpus comparison</strong>. There is no direct punctuation on either compared Russian alphabet. Actual punctuation/layer frequency and Shift interactions require a suitable phone-use corpus; rare-letter popup movement/time also remains unmeasured.</p><p class="see"><strong>You should see:</strong> preserved current access, with no speculative Shift or layer change smuggled into the proposal.</p></li>
<li><h2>Read the posture sensitivity before treating this as better</h2><p>The search assumes two-thumb portrait typing, no cross-gap reaches, equal targets and bottom-center anchors: left column 3/right column 3 at the bottom alphabet row. It uses Euclidean touch travel, not physical-key actuation or measured thumb biomechanics. No phone model, millimeters, dp, hand size or actual grip is asserted.</p><p>Changing vertical/horizontal pitch ratio from 0.7 to 1.3 retains the complete-path reduction: <strong>10.7–13.9%</strong>. But with both assumed rest anchors one column nearer the center gap at ratio 0.7, reach becomes <strong>1.253 → 1.286u (2.6% worse)</strong>. At the nominal aspect ratio this posture gives only a 4.0% reach reduction, versus 25.9% with central anchors. Physical reach can change the recommendation.</p><p>Equal-size targets mean this study does not estimate accuracy or target-acquisition time. Bigger letters do not create bigger hit targets. On a narrow phone, five targets per half may be a reach/precision compromise that moving letters cannot repair. Maximum observed thumb jump is unchanged at 4.472u. Learning cost is high: nearly the entire alphabet moves; there is no familiarity-preserving constraint or claimed global optimum.</p><p class="see"><strong>You should see:</strong> a promising model candidate, not permission to replace a QA-passed keyboard.</p></li>
<li><h2>Keep the next piece small and research-only</h2><p>The useful next design input is the owner's already-requested thumb/grid context, now narrowed to actual comfortable phone reach and posture. A paper/static comparison can decide whether lower-center anchors are credible before any implementation is considered. If they are not, re-score this candidate against the actual reachable zones instead of chasing same-thumb percentage.</p><p class="see"><strong>You should see:</strong> no new repeated question, no device automation and no deployment request.</p><p class="decision">Reply here when useful: keep researching / revise the assumed thumb reach. No approval or action is required now.</p></li></ol>
<details><summary>Evidence, reproduction and limits</summary><p>Corpus: <a href="https://github.com/UniversalDependencies/UD_Russian-GSD/tree/r2.15">UD Russian-GSD r2.15</a>, wiki genre. <a href="https://raw.githubusercontent.com/UniversalDependencies/UD_Russian-GSD/r2.15/README.md">Treebank README</a> lists contributors Ryan McDonald, Vitaly Nikolaev and Olga Lyashevskaya and CC BY-SA 4.0; underlying text rights are distinct from Google annotations. This is encyclopedic public prose, not Slava's phone typing or the historical corpus.</p><p>For each # text field: lowercase; replace each maximal non-Russian-letter run with one space; strip sentence edges; preserve ё/ъ/э; count all remaining unigrams and adjacent pairs within each sentence. No punctuation is bridged without a space. Search uses train only: {r['train']['sentences']:,} sentences, {r['train']['characters']:,} characters, {r['train']['pairs']:,} pairs. Unseen test: {r['test']['sentences']:,} sentences, {r['test']['characters']:,} characters, {r['test']['pairs']:,} pairs. Uppercase is normalized and Shift cost omitted equally. No private prompts were opened, extracted or reported.</p><p>Search objective: adjacent same-thumb distance + 0.25×mean anchor reach + 0.35×same-thumb different-target rate + 3×(right load−0.5)² + H×popup-letter rate. H=3 abstract units (not milliseconds); evaluated H=1,3,6. Popup target modeled at parent center, extra movement unknown. Equal popup incidence makes this sensitivity a common additive offset, not evidence validating popup latency. The whole-thumb path check is held-out evaluation, not the optimized objective. Width and vertical ratios are geometric proxies; no Fitts-law time coefficients or accuracy model were fitted.</p><p>Search: seed {r['seed']}, three restarts × {r['steps_per_restart']:,} swaps. Not an exhaustive optimum; weighted-score reduction is not a measured speedup. Candidate was selected using train only; all nine aspect/hold checks and nine aspect/anchor checks are in the results. Public source bytes are identified by SHA-256 in counts; re-downloading checks the test digest. Branch tags can theoretically move, so the saved digest binds this run.</p><p>Artifacts: <a href="study.py">study.py</a>, <a href="evaluate.py">evaluate.py</a>, <a href="counts.json">counts/provenance</a>, <a href="results.json">all results</a>, <a href="render_report.py">report renderer</a>. Reproduce from this directory: <code>nice -n 15 python3 -B study.py &amp;&amp; nice -n 15 python3 -B evaluate.py &amp;&amp; python3 -B render_report.py</code>. Check available memory and coordinate before running. This run had 13 GiB available. Source digest, alphabet uniqueness/completeness, test character totals, finite metrics and same-target/same-thumb consistency assertions passed.</p><p>Source review only: no app-source edits, generated Android resources, device input/gestures/screenshots, installation, firmware edits, flashing, merge or deployment. The independent Cantor candidate was inspected read-only and is not reused as thumb evidence. Supported browser access returned 401 before filesystem context was supplied; no authentication bypass was attempted. Web search was unavailable; no unsupported literature claims are made.</p></details><footer>I will keep this as research. I will not change the Android keyboard or touch the phone without a separate implementation order.</footer></main></body></html>'''
(ROOT/'proposal.html').write_text(head+body)
print(ROOT/'proposal.html')
